from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_GRID_LIMITS = {
    "width": (1, MAX_DIM, "bad width"),
    "height": (1, MAX_DIM, "bad height"),
    "cell_size": (1, None, "bad cell size"),
}


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not {"grid", "observations", "fill_value"} <= raw.keys():
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not {"width", "height", "cell_size"} <= grid.keys():
        return {"ok": False, "error": "bad grid"}
    for field, (lo, hi, error) in _GRID_LIMITS.items():
        value = grid[field]
        if not (isinstance(value, int) and lo <= value and (hi is None or value <= hi)):
            return {"ok": False, "error": error}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]

    sums: dict = {}
    counts: dict = {}
    degraded: dict = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not _valid_observation(obs):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _map_coord(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _map_coord(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _build_grid(sums, counts, degraded, width, height, raw["fill_value"])
    coverage = len(counts) * 100 // (width * height)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage),
    }


def _valid_observation(obs: object) -> bool:
    return (
        isinstance(obs, dict)
        and all(isinstance(obs.get(field), int) for field in ("x", "y", "value", "quality"))
        and 0 <= obs["quality"] <= 100
    )


def _map_coord(value: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    index = value // cell_size
    if index >= dim:
        if value - dim * cell_size >= tolerance:
            return None
